std::string utf(const fs::path& p){auto s=p.u8string();return {reinterpret_cast<const char*>(s.data()),s.size()};}
std::wstring wide(const std::string& s){auto n=MultiByteToWideChar(CP_UTF8,0,s.data(),int(s.size()),nullptr,0);std::wstring w(n,0);MultiByteToWideChar(CP_UTF8,0,s.data(),int(s.size()),w.data(),n);return w;}
std::string hash(const std::string& s){return ayt::crypto::createHash(ayt::crypto::HashAlgo::SHA256)->hashString(reinterpret_cast<const uint8_t*>(s.data()),s.size());}
std::string read(const fs::path& p,size_t max=2*1024*1024){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()<0||uint64_t(f.tellg())>max)throw std::runtime_error("file_unavailable");std::string s(size_t(f.tellg()),0);f.seekg(0);f.read(s.data(),s.size());if(!f&&!s.empty())throw std::runtime_error("file_read_failed");return s;}
void save(const fs::path& p,const J& j){fs::create_directories(p.parent_path());auto tmp=p;tmp+=".new";{std::ofstream f(tmp,std::ios::binary);f<<j.dump(2);if(!f)throw std::runtime_error("write_failed");}if(!MoveFileExW(tmp.c_str(),p.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("write_failed");}
