 settings={{"defaultProgramRoot",utf(home/"Trial"/"program")}};const auto fallback=settings;try{auto candidate=J::parse(read(settingsFile,128*1024));if(candidate.at("schema").get<int>()!=1||!candidate.at("defaultProgramRoot").is_string()||!candidate.at("powershell").is_string()||!candidate.at("source").is_object())throw std::runtime_error("launcher_settings_invalid");settings=std::move(candidate);home=fs::absolute(settingsFile).parent_path();prepareSource();}catch(const std::exception& e){if(!settings.contains("defaultProgramRoot"))settings=fallback;status=errorText(e.what());}
